INSERT INTO Invoice (InvoiceId, CustomerId, InvoiceDate, BillingCountry, Total) WITH RECURSIVE n(x) AS (SELECT 1 UNION ALL SELECT x+1 FROM n WHERE x<10) SELECT x, 1, '2024-01-01 00:00:00', 'A', 1.00 FROM n;
